import { ref } from 'vue'

export type NotificationType = 'info' | 'success' | 'warning' | 'error'

export interface NotificationAction {
  label: string
  handler: () => void
}

export interface Notification {
  id: string
  type: NotificationType
  message: string
  duration?: number
  action?: NotificationAction
}

const notifications = ref<Notification[]>([])

export function useNotification() {
  function addNotification(notification: Omit<Notification, 'id'>) {
    const id = Date.now().toString() + Math.random().toString(36).substr(2, 5)
    const newNotification: Notification = {
      ...notification,
      id,
      duration: notification.duration ?? 4000,
    }
    notifications.value.push(newNotification)

    if (newNotification.duration > 0) {
      setTimeout(() => {
        removeNotification(id)
      }, newNotification.duration)
    }
  }

  function removeNotification(id: string) {
    const index = notifications.value.findIndex((n) => n.id === id)
    if (index !== -1) notifications.value.splice(index, 1)
  }

  return {
    notifications,
    addNotification,
    removeNotification,
  }
}
<template>
  <Teleport to="body">
    <div class="modal-overlay" @click.self="emit('close')">
      <div class="modal">
        <div class="modal-header">
          <h3>{{ modalTitle }}</h3>
          <button class="close-btn" @click="emit('close')">
            <X :size="20" />
          </button>
        </div>

        <form @submit.prevent="handleSubmit">
          <div class="form-group">
            <label>Название</label>
            <input
              v-model="form.title"
              type="text"
              :placeholder="titlePlaceholder"
              required
            />
          </div>

          <div class="form-group">
            <label>Описание</label>
            <input
              v-model="form.description"
              type="text"
              placeholder="Дополнительные детали (необязательно)"
            />
          </div>

          <div class="form-row" v-if="!hideType">
            <div class="form-group">
              <label>Тип</label>
              <div class="select-wrapper">
                <select v-model="form.type">
                  <option value="HABIT">Привычка</option>
                  <option value="TASK_DAY">На день</option>
                  <option value="TASK_WEEK">На неделю</option>
                  <option value="TASK_MONTH">На месяц</option>
                  <option value="TASK_YEAR">На год</option>
                </select>
                <ChevronDown :size="16" class="select-icon" />
              </div>
            </div>

            <div class="form-group" v-if="form.type !== 'HABIT'">
              <label>Срок</label>
              <div class="date-wrapper">
                <input type="date" v-model="form.targetDate" />
                <Calendar :size="16" class="date-icon" />
              </div>
            </div>
          </div>

          <div class="form-group">
            <label>Теги</label>
            <div class="tags-cloud">
              <template v-for="tag in tagsStore.tags" :key="tag.id">
                <div class="tag-wrapper">
                  <button
                    type="button"
                    class="tag-btn"
                    :class="{ active: form.tagIds.includes(tag.id) }"
                    @click="toggleTag(tag.id)"
                  >
                    {{ tag.name }}
                  </button>
                  <button
                    v-if="!tag.isSystem"
                    class="tag-delete"
                    @click.stop="deleteTag(tag.id)"
                    title="Удалить тег"
                  >
                    <X :size="14" />
                  </button>
                </div>
              </template>
              <button
                type="button"
                class="tag-btn add-tag-btn"
                @click="openAddTagModal"
                title="Добавить тег"
              >
                <Plus :size="16" /> Добавить
              </button>
            </div>
          </div>

          <div class="form-actions">
            <button type="button" class="btn-secondary" @click="emit('close')">
              Отмена
            </button>
            <button type="submit" class="btn-primary">
              {{ editing ? 'Сохранить' : submitButtonText }}
            </button>
          </div>
        </form>
      </div>
    </div>

    <!-- Модалка добавления тега -->
    <Teleport to="body">
      <div
        v-if="showAddTagModal"
        class="modal-overlay"
        @click.self="closeAddTagModal"
      >
        <div class="modal tag-modal">
          <div class="modal-header">
            <h4>Новый тег</h4>
            <button class="close-btn" @click="closeAddTagModal">
              <X :size="18" />
            </button>
          </div>
          <form @submit.prevent="createTag">
            <div class="form-group">
              <label>Название</label>
              <input
                v-model="newTagName"
                type="text"
                placeholder="#важно"
                required
              />
            </div>
            <div class="form-group">
              <label>Ветка</label>
              <div class="select-wrapper">
                <select v-model="newTagBranchId" required>
                  <option value="FIN">Финансы</option>
                  <option value="BODY">Тело</option>
                  <option value="MIND">Интеллект</option>
                  <option value="LDR">Лидерство</option>
                </select>
                <ChevronDown :size="16" class="select-icon" />
              </div>
            </div>
            <div class="form-actions">
              <button
                type="button"
                class="btn-secondary"
                @click="closeAddTagModal"
              >
                Отмена
              </button>
              <button type="submit" class="btn-primary">Создать</button>
            </div>
          </form>
        </div>
      </div>
    </Teleport>
  </Teleport>
</template>

<script setup lang="ts">
import { reactive, watch, ref, computed } from 'vue'
import { X, ChevronDown, Calendar, Plus } from 'lucide-vue-next'
import { useTagsStore } from '~/stores/tags.store'
import { useTasksStore } from '~/stores/tasks.store'
import { useNotification } from '~/composables/useNotification'
import type { Task } from '~/types/task.types'

const props = defineProps<{
  task?: Task
  defaultType?: string
  hideType?: boolean
}>()

const emit = defineEmits<{
  (e: 'close'): void
  (e: 'save', data: any): void
}>()

const tagsStore = useTagsStore()
const tasksStore = useTasksStore()
const { addNotification } = useNotification()
const editing = computed(() => !!props.task)

const form = reactive({
  title: '',
  description: '',
  type: props.defaultType || 'HABIT',
  targetDate: '',
  tagIds: [] as string[],
})

// Динамические тексты в зависимости от типа
const modalTitle = computed(() => {
  if (editing.value) return 'Редактирование'
  return form.type === 'HABIT' ? 'Новая привычка' : 'Новая задача'
})

const submitButtonText = computed(() => {
  return form.type === 'HABIT' ? 'Добавить привычку' : 'Создать задачу'
})

const titlePlaceholder = computed(() => {
  return form.type === 'HABIT'
    ? 'Например: Пить воду'
    : 'Например: Прочитать 20 страниц'
})

watch(
  () => props.task,
  (newTask) => {
    if (newTask) {
      form.title = newTask.title
      form.description = newTask.description || ''
      form.type = newTask.type
      form.targetDate = newTask.targetDate || ''
      form.tagIds = [...newTask.tagIds]
    }
  },
  { immediate: true }
)

// Если задан defaultType, синхронизируем его, но только при создании
watch(
  () => props.defaultType,
  (newType) => {
    if (!editing.value && newType) {
      form.type = newType
    }
  },
  { immediate: true }
)

function toggleTag(tagId: string) {
  const index = form.tagIds.indexOf(tagId)
  if (index === -1) {
    form.tagIds.push(tagId)
  } else {
    form.tagIds.splice(index, 1)
  }
}

function handleSubmit() {
  if (editing.value) {
    emit('save', { ...form })
  } else {
    const result = tasksStore.addTask({ ...form })
    if (result) {
      addNotification({
        type: 'success',
        message:
          form.type === 'HABIT'
            ? `Привычка «${result.title}» добавлена`
            : `«${result.title}» добавлено`,
      })
      emit('close')
    } else {
      addNotification({
        type: 'warning',
        message: 'Лимит задач на этот период исчерпан',
      })
    }
  }
}

// Логика добавления/удаления тегов
const showAddTagModal = ref(false)
const newTagName = ref('')
const newTagBranchId = ref<'FIN' | 'BODY' | 'MIND' | 'LDR'>('FIN')

function openAddTagModal() {
  newTagName.value = ''
  newTagBranchId.value = 'FIN'
  showAddTagModal.value = true
}

function closeAddTagModal() {
  showAddTagModal.value = false
}

function createTag() {
  if (!newTagName.value.trim()) return
  let name = newTagName.value.trim()
  if (!name.startsWith('#')) name = '#' + name

  const existing = tagsStore.tags.find(
    (t) => t.name.toLowerCase() === name.toLowerCase()
  )
  if (existing) {
    addNotification({ type: 'warning', message: 'Такой тег уже существует' })
    return
  }

  tagsStore.addTag({ name, branchId: newTagBranchId.value, order: 999 })
  addNotification({ type: 'success', message: `Тег «${name}» добавлен` })
  closeAddTagModal()
}

function deleteTag(tagId: string) {
  const success = tagsStore.deleteTag(tagId)
  if (success) {
    addNotification({ type: 'success', message: 'Тег удалён' })
    const index = form.tagIds.indexOf(tagId)
    if (index !== -1) form.tagIds.splice(index, 1)
  } else {
    addNotification({ type: 'error', message: 'Нельзя удалить системный тег' })
  }
}
</script>

<style scoped lang="scss">
.modal-overlay {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1000;
  padding: 16px;
  background: rgba(0, 0, 0, 0.7);
  backdrop-filter: blur(6px);
}

.modal {
  width: 100%;
  max-width: 480px;
  max-height: 90vh;
  overflow-y: auto;
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--border);
  background: var(--bg);
  @include glass;
  color: var(--accent);

  &::-webkit-scrollbar {
    width: 4px;
  }
  &::-webkit-scrollbar-track {
    background: transparent;
  }
  &::-webkit-scrollbar-thumb {
    background: var(--border);
    border-radius: 2px;
  }
}

.tag-modal {
  max-width: 380px;
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px 0;

  h3,
  h4 {
    font-weight: 600;
    letter-spacing: -0.01em;
  }
  h3 {
    font-size: 1.3rem;
  }
  h4 {
    font-size: 1.1rem;
  }

  .close-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    color: var(--dim);
    background: transparent;
    border: none;
    cursor: pointer;
    transition: all var(--transition-standard);

    &:hover {
      background: var(--surface);
      color: var(--accent);
    }
  }
}

form {
  padding: 20px 24px 24px;
}

.form-group {
  margin-bottom: 20px;

  label {
    display: block;
    margin-bottom: 8px;
    font-size: 0.85rem;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: var(--dim);
  }

  input,
  select {
    width: 100%;
    padding: 12px 16px;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--border-radius-md);
    color: var(--accent);
    font-size: 1rem;
    transition: border-color var(--transition-standard);

    &::placeholder {
      color: var(--dim);
      opacity: 0.6;
    }

    &:focus {
      border-color: var(--accent);
      outline: none;
    }
  }
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;

  @media (max-width: 500px) {
    grid-template-columns: 1fr;
    gap: 0;
  }
}

.select-wrapper {
  position: relative;

  select {
    appearance: none;
    padding-right: 40px;
    cursor: pointer;
  }

  .select-icon {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--dim);
    pointer-events: none;
  }
}

.date-wrapper {
  position: relative;

  input[type='date'] {
    appearance: none;
    padding-right: 40px;
    cursor: pointer;

    &::-webkit-calendar-picker-indicator {
      opacity: 0;
      position: absolute;
      right: 0;
      width: 100%;
      height: 100%;
      cursor: pointer;
    }
  }

  .date-icon {
    position: absolute;
    right: 16px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--dim);
    pointer-events: none;
  }
}

.tags-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;

  .tag-wrapper {
    position: relative;
    display: inline-flex;
    align-items: center;
  }

  .tag-btn {
    padding: 8px 14px;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: var(--border-radius-sm);
    color: var(--dim);
    font-size: 0.85rem;
    font-weight: 500;
    transition: all var(--transition-standard);
    cursor: pointer;

    &:hover {
      background: var(--border);
      color: var(--accent);
    }

    &.active {
      background: var(--accent);
      border-color: var(--accent);
      color: var(--bg);
    }
  }

  .tag-delete {
    position: absolute;
    top: -6px;
    right: -6px;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background: var(--surface);
    border: 1px solid var(--border);
    color: var(--dim);
    cursor: pointer;
    transition: all 0.2s;
    padding: 0;

    &:hover {
      background: var(--error);
      color: white;
      border-color: var(--error);
    }
  }

  .add-tag-btn {
    background: transparent;
    border: 1px dashed var(--border);
    color: var(--dim);
    display: flex;
    align-items: center;
    gap: 4px;

    &:hover {
      background: var(--surface);
      border-style: solid;
    }
  }
}

.form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 28px;

  button {
    padding: 12px 24px;
    border-radius: var(--border-radius-md);
    font-weight: 500;
    font-size: 0.95rem;
    transition: all var(--transition-standard);
    cursor: pointer;
    border: none;
  }

  .btn-secondary {
    background: transparent;
    color: var(--dim);

    &:hover {
      background: var(--surface);
      color: var(--accent);
    }
  }

  .btn-primary {
    background: var(--accent);
    color: var(--bg);

    &:hover {
      opacity: 0.9;
      transform: translateY(-1px);
      box-shadow: var(--shadow-sm);
    }
  }
}
</style>
